(function(root){
function rng(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t^=t+Math.imul(t^t>>>7,61|t);return((t^t>>>14)>>>0)/4294967296}}
function solve(p,limit=2,fixed){const out=[],cols=new Set(),groups=new Set(),a=Array(p.n).fill(-1);function rec(r){if(out.length>=limit)return;if(r===p.n){out.push([...a]);return}for(let c=0;c<p.n;c++){if(fixed&&fixed[r]>=0&&fixed[r]!==c)continue;const g=p.regions[r*p.n+c];if(cols.has(c)||groups.has(g)||r&&Math.abs(a[r-1]-c)<=1)continue;a[r]=c;cols.add(c);groups.add(g);rec(r+1);cols.delete(c);groups.delete(g)}a[r]=-1}rec(0);return out}
function conflicts(p,a){const bad=new Set();for(let r=0;r<p.n;r++){if(a[r]<0)continue;for(let s=r+1;s<p.n;s++){if(a[s]<0)continue;if(a[r]===a[s]||p.regions[r*p.n+a[r]]===p.regions[s*p.n+a[s]]||s-r===1&&Math.abs(a[r]-a[s])<=1){bad.add(r*p.n+a[r]);bad.add(s*p.n+a[s])}}}return [...bad]}
function isWin(p,a){return a.length===p.n&&a.every(c=>Number.isInteger(c)&&c>=0&&c<p.n)&&conflicts(p,a).length===0}
function generate(n,seed){const random=rng(seed),shuffle=a=>a.sort(()=>random()-.5);for(let attempt=0;attempt<30000;attempt++){let perm=[];function pick(){if(perm.length===n)return true;for(const c of shuffle(Array.from({length:n},(_,i)=>i))){if(!perm.includes(c)&&(!perm.length||Math.abs(c-perm.at(-1))>1)){perm.push(c);if(pick())return true;perm.pop()}}return false}pick();const regions=Array(n*n).fill(-1);perm.forEach((c,r)=>regions[r*n+c]=r);let left=n*n-n;while(left){const frontier=[];for(let i=0;i<regions.length;i++)if(regions[i]>=0){let r=Math.floor(i/n),c=i%n;for(const [dy,dx]of [[0,1],[0,-1],[1,0],[-1,0]]){let y=r+dy,x=c+dx,j=y*n+x;if(y>=0&&y<n&&x>=0&&x<n&&regions[j]<0)frontier.push([j,regions[i]])}}const [i,g]=frontier[Math.floor(random()*frontier.length)];regions[i]=g;left--}const p={n,regions};if(solve(p).length===1)return p}throw Error('Unable to generate unique board')}
const api={rng,solve,conflicts,isWin,generate};if(typeof module!=='undefined')module.exports=api;else root.Puzzle=api;
})(typeof window!=='undefined'?window:globalThis);
